import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 33 · everyday recipe: stuffed cabbage rolls (Google Trends 3/11: cabbage among rising dinner questions)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, the best cook on our street in nineteen fifty-five didn't speak much English. Mrs. Kowalski, from Poland, two doors down. Every Saturday, the smell of her cabbage rolls came through our kitchen window, and my brother Danny would stand on the back porch and sniff like a hound dog until she waved him over.""",
   "stuffed cabbage rolls pot tomato", "LIKE A HOUND DOG")
sc("""Today, people tell me their cabbage rolls fall apart in the pot, or the leaves are tough as paper, or the filling is dry. So tonight I'm giving you Mrs. Kowalski's cabbage rolls, every step, and the four mistakes that make them fall apart. And stay with me, because the trick for the leaves is the one that changed everything for me, and it uses your freezer.""",
   "cabbage rolls falling apart pot", "THEY FALL APART")

ch("Mrs. Kowalski's kitchen")
sc("""In the steel towns of Ohio in the fifties, half the families came from Poland, Hungary, Slovakia and Ukraine. And every one of those grandmothers made cabbage rolls. The Poles called them golabki, little pigeons. The Hungarians called them toltott kaposzta. Mrs. Kowalski said every grandmother thinks hers are the only right ones, and every grandmother is right.""",
   "1950s Ohio steel town neighborhood", "LITTLE PIGEONS")
sc("""When I was ten, Mrs. Kowalski let me help. She sat me on a stool, gave me a big bowl of filling and a stack of soft cabbage leaves, and showed me how to roll them, like a little package. My first ones looked like a dog had chewed them. She put them in the pot anyway, right next to hers, and when they were done, she said mine were the best. She lied beautifully.""",
   "child rolling cabbage leaves kitchen", "SHE LIED BEAUTIFULLY")
sc("""Cabbage rolls were what you made when you had a cabbage, a pound of meat, and a family to feed. One pound of ground meat and a cup of rice makes sixteen big rolls, enough for a family of six with leftovers. In nineteen fifty-five, the whole pot cost Mrs. Kowalski about a dollar. Today it's about twelve. Still the cheapest Sunday dinner I know.""",
   "pot of cabbage rolls family table", "ABOUT TWELVE DOLLARS")

ch("What you need")
sc("""Here's what you need, honey. One large head of green cabbage, about three pounds. One pound of ground beef, or half beef and half pork, which is what Mrs. Kowalski used. Pork makes them juicier. One cup of white rice, uncooked. One onion, chopped fine. Two cloves of garlic. One egg. Salt, pepper, and a teaspoon of paprika.""",
   "cabbage head ground meat rice", "HALF BEEF, HALF PORK")
sc("""For the sauce. One big can of crushed tomatoes, twenty-eight ounces. One can of tomato soup, the way every Ohio grandmother did it, or a small can of tomato sauce. A tablespoon of brown sugar. A tablespoon of vinegar or lemon juice. And a cup of water or broth. Some families add a jar of sauerkraut on the bottom of the pot. Mrs. Kowalski did, and so do I.""",
   "crushed tomatoes can sauerkraut jar", "SAUERKRAUT ON THE BOTTOM")

ch("The leaves")
sc("""Now the leaves, and this is where most people give up. The old way is to boil the whole head of cabbage in a big pot, and peel off the leaves one by one as they soften, with tongs, burning your fingers. Mrs. Kowalski did it that way her whole life. It works, but it's a fight. Here's the trick I promised you.""",
   "boiling cabbage head pot tongs", "IT'S A FIGHT")
sc("""Put the whole head of cabbage in the freezer the night before. Then take it out in the morning and let it thaw on the counter for the day, or in the icebox for two days. When it thaws, the leaves come off soft and bendy, like they were cooked, and they don't tear. No boiling, no burned fingers. My daughter-in-law taught me that in nineteen ninety, and I wished I'd known it forty years sooner.""",
   "frozen cabbage thawing leaves", "THE FREEZER TRICK")
sc("""Either way, take your soft leaves and look at the thick rib down the middle of each one. With a small knife, shave that rib down flat, so it's as thin as the rest of the leaf. Don't cut it out. Just shave it thin. That thick rib is mistake number one, the reason rolls crack and won't stay closed.""",
   "shaving cabbage leaf rib knife", "SHAVE THE RIB")

sc("""And pick the right cabbage at the store. Look for a big, heavy head with loose outer leaves, not a small, tight, hard one. The loose ones have bigger, softer leaves that roll easier. Savoy cabbage, the crinkly kind, is even easier to roll, but it's more delicate. Mrs. Kowalski squeezed every cabbage at the market like she was checking a melon.""",
   "cabbage heads market stand", "LIKE CHECKING A MELON")

ch("The filling")
sc("""Now the filling. Cook the chopped onion in a little butter until it's soft and sweet, about eight minutes, and let it cool. Then in a big bowl, mix the meat, the uncooked rice, the cooled onion, the garlic, the egg, a teaspoon and a half of salt, pepper, paprika, and a quarter cup of the tomato sauce. Mix it with your hands, gently, just until it's together.""",
   "mixing meat rice filling bowl hands", "GENTLY, WITH YOUR HANDS")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. And now, mistake number two. Cooked rice. People cook the rice first, and then it gets mushy, and the filling turns to paste. Use raw rice. It cooks inside the roll and soaks up all the juice from the meat and the sauce. That's what keeps the filling moist.""",
   "uncooked white rice measuring cup", "USE RAW RICE")

ch("Rolling")
sc("""Step three, the rolling. Lay a leaf flat with the stem end toward you, the inside of the leaf facing up. Put about a quarter cup of filling near the stem end. Fold the bottom up over the filling, then fold in both sides, and roll it away from you, snug but not tight. Like a little package, or a burrito, my grandchildren say.""",
   "rolling stuffed cabbage leaf hands", "LIKE A LITTLE PACKAGE")
sc("""Mistake number three. Rolling them too tight. The rice swells as it cooks, and if the roll is too tight, it bursts open in the pot. Leave a little room. And don't overfill them. A quarter cup, no more. Mrs. Kowalski said, a cabbage roll is like a good coat. It should fit, but you should still be able to breathe.""",
   "cabbage rolls lined up seam down", "LIKE A GOOD COAT")

ch("The pot")
sc("""Step four. Take the torn leaves and the small ones you didn't use, and line the bottom of a big heavy pot with them, with the sauerkraut if you're using it. That bed keeps the rolls from scorching. Then lay the rolls on top, seam side down, packed close together, side by side, in layers. Packed close, they hold each other closed.""",
   "cabbage rolls packed in pot layers", "PACKED CLOSE")
sc("""So far, the freezer trick, shaving the rib, raw rice, a loose roll, and packing them close, seam down. Now mix the crushed tomatoes, tomato soup, brown sugar, vinegar and water, and pour it over the rolls, until it just about covers them. Cover the top with a few more cabbage leaves, then the lid.""",
   "pouring tomato sauce over cabbage rolls", "JUST ABOUT COVERED")
sc("""Step five. Bring it to a gentle simmer on the stove, then cook it very low, covered, for an hour and a half. Or put it in a three hundred fifty degree oven for two hours. And here's mistake number four. A hard boil. Boiling tosses the rolls around and breaks them open. Gentle. Barely bubbling. Don't stir it. Just shake the pot a little now and then.""",
   "cabbage rolls simmering pot low", "DON'T STIR IT")

sc("""How do you know they're done? In a minute you'll smell it, honey, but here's the real test. Take one roll out, cut it in half, and taste the rice in the middle. If it's soft all the way through, they're done. If it's still a little hard, give them another twenty minutes. The cabbage should be so tender you can cut it with the side of a fork.""",
   "cutting cabbage roll in half fork", "TASTE THE RICE")

ch("Serving")
sc("""Lift them out gently with a big spoon, two or three per plate, and spoon the sauce over. Mrs. Kowalski put a spoon of sour cream on top and served them with mashed potatoes and rye bread. My father ate four and called them Polish pigs in a blanket, and Mrs. Kowalski would shake her wooden spoon at him and laugh.""",
   "cabbage rolls sour cream plate", "POLISH PIGS IN A BLANKET")
sc("""Cabbage rolls are even better the next day, honey. Every grandmother knows it. Keep them in the sauce in the icebox for four days, and warm them slowly. They also freeze beautifully, in the sauce, for three months. I make a double pot in January and freeze half, and on a cold Tuesday in February, dinner is already done.""",
   "leftover cabbage rolls container", "BETTER THE NEXT DAY")
sc("""And if you don't have time for rolling, make unstuffed cabbage. Brown the meat and onion in a pot, add chopped cabbage, the uncooked rice, the sauce and two cups of water, and simmer it covered for forty minutes. Same taste, one pot, no rolling. My granddaughter calls it lazy cabbage rolls, and she makes it every week.""",
   "cabbage beef rice skillet one pot", "LAZY CABBAGE ROLLS")

ch("Grandma's kitchen")
sc("""So one more time, honey. Freeze the cabbage the night before, so the leaves come off soft. Shave the rib. Raw rice in the filling. A quarter cup, rolled snug but not tight. A bed of leaves in the pot, rolls packed close and seam down. Tomato sauce with a little sugar and vinegar. Low and slow, never a hard boil. That's Mrs. Kowalski's cabbage rolls, and they never fall apart.""",
   "cabbage rolls dinner table family", "THEY NEVER FALL APART")
sc("""Tell me in the comments, sweetheart. What did your grandmother call them? Golabki, pigs in a blanket, or something else? I read every comment. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "warm kitchen evening stove pot", "WHAT DID SHE CALL THEM?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma33", "Cabbage Rolls EVERYONE's Grandma Made (Why Yours Fall APART)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Stuffed cabbage (Polish golabki, Hungarian toltott kaposzta) in Central and Eastern European immigrant communities of the Ohio steel towns.",
      "Recipe as written by Grandma Ruth: 1 large cabbage, 1 lb ground beef and pork, 1 cup uncooked white rice, 1 onion, 2 garlic cloves, 1 egg, salt, pepper, 1 tsp paprika; sauce of 28 oz crushed tomatoes, 1 can tomato soup, 1 tbsp brown sugar, 1 tbsp vinegar, 1 cup water; simmer covered 1 1/2 hours or 350 F for 2 hours."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
